#define MOD 1000000007
#define MAXN 1001

long long dp[MAXN][MAXN];

int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    // dp[i][j] = number of partitions of i into exactly j positive parts
    memset(dp, 0, sizeof(dp));

    // Base cases
    dp[0][0] = 1;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i && j <= k; j++) {
            // partitions of i into j parts:
            // = partitions of i-1 into j-1 parts (one part is 1, remove it)
            // + partitions of i-j into j parts (all parts >= 2, subtract 1 from each)
            dp[i][j] = dp[i-1][j-1];
            if (i - j >= 0) {
                dp[i][j] = (dp[i][j] + dp[i-j][j]) % MOD;
            }
        }
    }

    if (k > n || k <= 0) {
        printf("0\n");
    } else {
        printf("%lld\n", dp[n][k]);
    }

    return 0;
}

#include <stdio.h>

#define MOD 1000000007LL

int main(void) {
    long long n, k;
    if (scanf("%lld %lld", &n, &k) != 2) return 0;

    if (k <= 0 || n < k) {
        printf("0\n");
        return 0;
    }

    // Number of ways to write n as a sum of k positive integers
    // (indistinguishable balls, indistinguishable boxes, each box nonempty)
    // equals C(n-1, k-1).
    long long N = n - 1;
    long long R = k - 1;

    if (R > N) {
        printf("0\n");
        return 0;
    }

    if (R > N - R) R = N - R;

    long long ans = 1;
    for (long long i = 1; i <= R; i++) {
        ans = (ans * ((N - R + i) % MOD)) % MOD;

        // Fermat inverse of i modulo MOD
        long long base = i % MOD, exp = MOD - 2, inv = 1;
        while (exp > 0) {
            if (exp & 1) inv = (inv * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }

        ans = (ans * inv) % MOD;
    }

    printf("%lld\n", ans);
    return 0;
}

