using namespace std;

const long long MOD = 1e9 + 7;

long long power(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = result * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return result;
}

long long modInverse(long long a, long long mod) {
    return power(a, mod - 2, mod);
}

long long nCr(long long n, long long r, long long mod) {
    if (r < 0 || r > n) return 0;
    if (r == 0 || r == n) return 1;

    // Compute n! / (r! * (n-r)!)
    // For large n, we compute iteratively
    // min(r, n-r) to minimize computation
    if (r > n - r) r = n - r;

    long long num = 1, den = 1;
    for (long long i = 0; i < r; i++) {
        num = num * ((n - i) % mod) % mod;
        den = den * ((i + 1) % mod) % mod;
    }

    return num % mod * modInverse(den, mod) % mod;
}

