#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, k;
    cin >> n >> k;

    // Number of ways to distribute n indistinguishable balls
    // into k indistinguishable non-empty boxes equals the number
    // of integer partitions of n into exactly k positive parts.
    //
    // DP recurrence:
    // dp[i][j] = number of partitions of i into exactly j positive parts
    // dp[i][j] = dp[i-1][j-1] + dp[i-j][j]
    //
    // Explanation:
    // - Put 1 ball in each of the j boxes first, then partition remaining i-j
    //   balls into j boxes: dp[i-j][j]
    // - Or make one box contain exactly 1 ball and partition i-1 into j-1 boxes:
    //   dp[i-1][j-1]

    if (k > n || k <= 0 || n <= 0) {
        cout << 0 << '\n';
        return 0;
    }

    vector<vector<long long>> dp(n + 1, vector<long long>(k + 1, 0));
    dp[0][0] = 1;

    for (long long i = 1; i <= n; ++i) {
        for (long long j = 1; j <= k && j <= i; ++j) {
            dp[i][j] = dp[i - 1][j - 1];
            if (i >= j) {
                dp[i][j] = (dp[i][j] + dp[i - j][j]) % MOD;
            }
        }
    }

    cout << dp[n][k] % MOD << '\n';
    return 0;
}

