import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long n = fs.nextLong();
        long k = fs.nextLong();

        // Number of ways to distribute n indistinguishable balls
        // into k indistinguishable nonempty boxes
        // = number of partitions of n into exactly k positive parts.
        //
        // A standard DP:
        // p(i, j) = p(i-1, j-1) + p(i-j, j)
        //
        // where:
        // - p(i-1, j-1): one box has exactly 1 ball
        // - p(i-j, j): every box has at least 1, remove 1 from each box
        //
        // Base:
        // p(0, 0) = 1
        // p(i, 0) = 0 for i > 0
        // p(i, j) = 0 if j > i

        if (k < 0 || n < 0 || k > n) {
            System.out.println(0);
            return;
        }

        int N = (int) n;
        int K = (int) k;

        long[][] dp = new long[N + 1][K + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= N; i++) {
            for (int j = 1; j <= K && j <= i; j++) {
                long ways = dp[i - 1][j - 1];
                if (i >= j) {
                    ways += dp[i - j][j];
                }
                dp[i][j] = ways % MOD;
            }
        }

        System.out.println(dp[N][K] % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
